export const TEAM = [
  { initials: 'RM', name: 'Rajeev M P', role: 'Career Counsellor', detail: 'Sales Head', tone: 'lime' },
  { initials: 'RK', name: 'Rakshith Kumar B G', role: 'Admissions Head', detail: 'Partnerships', tone: 'teal' },
  { initials: 'RG', name: 'Raghavendra M', role: 'Operations Head', detail: 'Marketing', tone: 'ink' },
];

/** Timeline labels map existing About copy — no new company claims. */
export const STORY_PHASES = [
  {
    phase: 'Beginning',
    title: 'Direction, not guesswork',
    text: 'Students need direction, not guesswork.',
  },
  {
    phase: 'Growth',
    title: 'After 10th',
    text: 'We stay with them from stream choice after 10th.',
  },
  {
    phase: 'Transformation',
    title: 'Admission',
    text: 'Through college admission.',
  },
  {
    phase: 'Future',
    title: 'Placement prep',
    text: 'And placement prep.',
  },
];

/** Existing site visuals already used on Home / TransformationBanner. */
export const GALLERY = [
  {
    src: '/images/hero-1-desktop.webp',
    title: 'Career assessment',
    meta: 'Map aptitude and interest to a stream.',
    to: '/career-assessment',
    span: 'wide',
  },
  {
    src: '/images/hero-2-desktop.webp',
    title: 'KCET predictor',
    meta: 'Safe, moderate and dream colleges.',
    to: '/kcet-predictor',
    span: 'tall',
  },
  {
    src: '/images/hero-3-desktop.webp',
    title: 'PGCET predictor',
    meta: 'Postgraduate matches by rank.',
    to: '/pgcet-predictor',
    span: 'normal',
  },
  {
    src: '/images/student-to-professional.png',
    title: 'Compare colleges',
    meta: 'Fees, courses and rankings side by side.',
    to: '/college-compare',
    span: 'normal',
  },
  {
    src: '/images/hero-journey.png',
    title: 'Admission support',
    meta: 'Counsellor follow-through until you join.',
